<script setup lang="ts">
import { PhMagnifyingGlass,PhArrowRight,PhCrosshair,PhClipboardText,PhArrowClockwise } from '@phosphor-icons/vue'
import { getFindingSeverity,findingSeverities,type FindingSeverity } from '../types/severity'
import { findingStatuses,type Finding,type FindingStatus } from '../types/findings'
import type { WorkspaceNavigation } from '../types/workspace'
import { formatDate } from '../data/operations'
import type { RepairDialogTarget } from '../types/repairWork'
import {materialWorkLabel,workOrderCode,materialEditingAllowed} from '../utils/materialRequests'
const props=defineProps<{findings:Finding[];storageReady:boolean;storageError:string;viewerReady:boolean;navigation?:WorkspaceNavigation|null}>()
defineEmits<{open:[id:string];request:[id:string];repair:[target:RepairDialogTarget];backup:[];locate:[assetId:string];reload:[];aircraft:[]}>()
const severityFilter=ref<'all'|'urgent'|FindingSeverity>('all')
const query=ref(''),status=ref<'all'|'active'|FindingStatus>('all')
const filtered=computed(()=>props.findings.filter(f=>(status.value==='all'||(status.value==='active'?f.status!=='closed':f.status===status.value))&&(severityFilter.value==='all'||(severityFilter.value==='urgent'?['high','critical'].includes(getFindingSeverity(f)):getFindingSeverity(f)===severityFilter.value))&&`${f.title} ${f.description} ${f.componentLabel} ${f.sourceName}`.toLocaleLowerCase('id').includes(query.value.trim().toLocaleLowerCase('id'))))
const counts=computed(()=>({total:props.findings.length,open:props.findings.filter(f=>['open','rework'].includes(f.status)).length,progress:props.findings.filter(f=>f.status==='in_progress').length,review:props.findings.filter(f=>f.status==='awaiting_review').length,closed:props.findings.filter(f=>f.status==='closed').length}))
watch(()=>props.navigation?.id,()=>{if(!props.navigation){query.value='';status.value='all';severityFilter.value='all'}else if(props.navigation.tab==='work'){query.value='';status.value=props.navigation.work?.status??'all';severityFilter.value=props.navigation.work?.severity??'all'}},{immediate:true})
const code=workOrderCode
</script>
<template>
  <section class="operations-page work-page" aria-labelledby="work-title">
    <header class="operations-heading"><div><span class="operations-eyebrow">C208 / DAFTAR KERJA</span><h2 id="work-title">Pekerjaan dari temuan</h2><p>Satu temuan menjadi satu entri kerja. Status mengikuti catatan dan riwayat tindak lanjut.</p></div><div class="work-data-actions"><span class="data-origin local"><span /> Catatan browser ini</span><button class="button subtle open-backup" @click="$emit('backup')">Data & backup</button></div></header>
    <div class="operations-metrics work-metrics"><div><span>Seluruh pekerjaan</span><strong>{{ storageReady?counts.total:'—' }}</strong><small>Terhubung ke temuan</small></div><div><span>Terbuka / pengerjaan ulang</span><strong>{{ storageReady?counts.open:'—' }}</strong><small>Belum ditindaklanjuti</small></div><div><span>Ditindaklanjuti</span><strong>{{ storageReady?counts.progress:'—' }}</strong><small>Dalam alur pencatatan</small></div><div><span>Menunggu pemeriksaan</span><strong>{{ storageReady?counts.review:'—' }}</strong><small>Hasil perlu ditinjau</small></div><div><span>Ditutup</span><strong>{{ storageReady?counts.closed:'—' }}</strong><small>Catatan selesai</small></div></div>
    <div class="operations-section-heading"><div><h3>Daftar pekerjaan</h3><p>Perubahan di detail temuan langsung tercermin di sini.</p></div><span>{{ filtered.length }} pekerjaan</span></div>
    <div class="operations-filters"><label class="operations-search"><span class="sr-only">Cari pekerjaan</span><PhMagnifyingGlass :size="18" /><input v-model="query" aria-label="Cari pekerjaan" placeholder="Cari pekerjaan, komponen, atau pengamatan…" /></label><label class="operations-select"><span>Status</span><select v-model="status" aria-label="Filter status pekerjaan"><option value="all">Semua status</option><option value="active">Seluruh yang aktif</option><option v-for="(label,key) in findingStatuses" :key="key" :value="key">{{ label }}</option></select></label><label class="operations-select"><span>Kekritisan</span><select v-model="severityFilter" aria-label="Filter kekritisan pekerjaan"><option value="all">Semua tingkat</option><option value="urgent">Tinggi / kritis</option><option v-for="(label,key) in findingSeverities" :key="key" :value="key">{{ label }}</option></select></label></div>
    <div v-if="storageError" class="form-error" role="alert">{{ storageError }}<button class="button" @click="$emit('reload')"><PhArrowClockwise :size="16" /> Coba lagi</button></div>
    <p v-else-if="!storageReady" class="operations-empty" role="status">Membuka catatan pekerjaan…</p>
    <div v-else-if="!filtered.length" class="operations-empty"><PhClipboardText :size="34" /><h3>{{ findings.length?'Tidak ada pekerjaan yang sesuai':'Mulai dari temuan pada pesawat' }}</h3><p>{{ findings.length?'Ubah pencarian atau filter status.':'Catat temuan pada model, atau aktifkan Demo terarah untuk melihat tiga catatan contoh.' }}</p><button class="button subtle" @click="findings.length?(query='',status='all',severityFilter='all'):$emit('aircraft')">{{ findings.length?'Hapus filter':'Ke model 3D' }}<PhArrowRight :size="16" /></button></div>
    <div v-else class="work-records" role="list"><article v-for="finding in filtered" :key="finding.id" class="work-record" role="listitem" :data-finding-id="finding.id"><div class="work-record-main"><div class="work-record-meta"><span class="record-code">{{ code(finding) }}</span><span class="finding-status" :class="finding.status">{{ findingStatuses[finding.status] }}</span><SeverityBadge :severity="getFindingSeverity(finding)" /><span v-if="finding.sample" class="sample-label">Data contoh</span><span v-if="finding.priority==='high'" class="priority-label">Prioritas tinggi</span></div><h4>{{ finding.title }}</h4><p>{{ finding.componentLabel }} <span>·</span> {{ finding.sourceName }} <span>·</span> {{ finding.photos.length }} foto</p><p v-if="materialWorkLabel(finding)" class="work-material-state"><span class="material-status" :class="(finding.materialRequests??[]).some(r=>r.status==='requested')?'requested':'ready'">{{ materialWorkLabel(finding) }}</span><small>{{ finding.materialRequests?.length }} permintaan</small></p><small>Diperbarui {{ formatDate(finding.updatedAt) }}</small></div><div class="work-record-actions"><button v-if="finding.status!=='closed'" class="button subtle work-repair-action" @click="$emit('repair',{findingId:finding.id,mode:finding.status==='awaiting_review'?'review':'record'})">{{ finding.status==='awaiting_review'?'Periksa hasil':'Kartu pengerjaan' }}</button><button class="button subtle request-material" :disabled="!storageReady||!materialEditingAllowed(finding)" :title="finding.status==='closed'?'Buka kembali pekerjaan melalui detail untuk mengajukan part.':'Ajukan material untuk pekerjaan ini'" @click="$emit('request',finding.id)">Request sparepart</button><button class="button primary" @click="$emit('open',finding.id)">Detail & tindak lanjut<PhArrowRight :size="16" /></button><button class="button subtle" :disabled="!viewerReady" @click="$emit('locate',finding.assetId)"><PhCrosshair :size="16" /> Lokasi 3D</button></div></article></div>
  </section>
</template>
